document.querySelectorAll("pre > code").forEach(e=>{const s=e.closest("pre");if(!s)return;const n=s.parentNode,t=document.createElement("button");t.classList.add("copy"),t.innerText="Copy";function o(){t.innerText="Copied!",setTimeout(()=>{t.innerText="Copy"},2e3)}t.addEventListener("click",async()=>{const t=e.textContent.trim();if(!navigator.clipboard){console.warn("Clipboard API not supported");return}try{await navigator.clipboard.writeText(e.textContent),o()}catch(e){console.error("Copy failed:",e)}}),n.classList.contains("highlight")?n.appendChild(t):n.closest("table")?n.closest("table").appendChild(t):s.appendChild(t)})